public static class Littoral35V6Layout {
 const string A="Assets/Prototype_Maquis/Art/Littoral35V6",V="Assets/Prototype_Maquis/Art/MaquisV2";
 static Transform ext,second;static TourLittoralRoute route;static Vector3[] points;static Material stone,mortar,soil,rock;static Vector3 towerCentre;static Quaternion towerRot;static System.Random rng;
 static float R(float a,float b){return a+(float)rng.NextDouble()*(b-a);}
 static Transform Group(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g.transform;}
 static void Record(GameObject g){foreach(var c in g.GetComponentsInChildren<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
 static Material CopyMat(Material src,string n){var m=new Material(src);m.name=n;AssetDatabase.CreateAsset(m,A+"/Materials/"+n+".mat");return m;}
 static Mesh MeshAsset(string n,Vector3[] v,int[] t,Color[] c){var m=new Mesh();m.name=n;m.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;m.vertices=v;m.triangles=t;m.colors=c;m.uv=v.Select(p=>new Vector2(p.x,p.z)).ToArray();m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.CreateAsset(m,A+"/Meshes/"+n+".asset");return m;}
 static GameObject Surface(string n,Mesh m,Material mat,Transform parent,bool collision){var go=new GameObject(n);go.transform.SetParent(parent,false);go.AddComponent<MeshFilter>().sharedMesh=m;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;if(collision)go.AddComponent<MeshCollider>().sharedMesh=m;return go;}
 static Vector3 Cat(Vector3 a,Vector3 b,Vector3 c,Vector3 d,float t){return .5f*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t);}
 static void Path(){var list=route.coastPoints.ToList();var knots=new[]{list[list.Count-2],list.Last(),new Vector3(3.6f,-.42f,22.4f),new Vector3(5.3f,-.66f,26.8f),new Vector3(4.5f,-.50f,31.2f),new Vector3(6.4f,-.78f,35.6f),new Vector3(5.8f,-.65f,40.4f),new Vector3(7f,-.8f,45f)};for(int i=1;i<knots.Length-2;i++)for(int j=1;j<=36;j++)list.Add(Cat(knots[i-1],knots[i],knots[i+1],knots[i+2],j/36f));
  var final=new List<Vector3>{list[0]};float length=0;for(int i=1;i<list.Count;i++){float d=Vector3.Distance(list[i-1],list[i]);if(length+d>=35){final.Add(Vector3.Lerp(list[i-1],list[i],(35-length)/d));break;}final.Add(list[i]);length+=d;}points=final.ToArray();route.Configure(points);if(Mathf.Abs(route.Length-35)>.001f)throw new Exception("35m route failed");
  var tangent=Vector3.ProjectOnPlane(points.Last()-points[points.Length-4],Vector3.up).normalized;towerCentre=points.Last()+tangent*4.15f-Vector3.up*.1f;towerRot=Quaternion.LookRotation(tangent);
 }
 static void Near(Vector3 p,out Vector3 q,out float d){float best=float.MaxValue;q=points[0];for(int i=1;i<points.Length;i++){var a=points[i-1];var b=points[i];var ab=b-a;float tt=Mathf.Clamp01(((p.x-a.x)*ab.x+(p.z-a.z)*ab.z)/Mathf.Max(.0001f,ab.x*ab.x+ab.z*ab.z));var v=Vector3.Lerp(a,b,tt);float dd=(p.x-v.x)*(p.x-v.x)+(p.z-v.z)*(p.z-v.z);if(dd<best){best=dd;q=v;}}d=Mathf.Sqrt(best);}
 static float Height(float x,float z){var p=new Vector3(x,0,z);Vector3 q;float d;Near(p,out q,out d);float left=q.x-x;float shoulder=Mathf.SmoothStep(0,1,(d-1.05f)/3.8f);float h=q.y+shoulder*(left>0?2.8f+1.5f*Mathf.PerlinNoise(x*.17f,z*.14f):.25f);h+=Mathf.SmoothStep(0,1,(d-.9f)/3)*.22f*Mathf.Sin(x*.65f+z*.33f);
  float shore=Mathf.Max(q.x+3.0f,6.8f+1.4f*Mathf.Sin(z*.11f));h=Mathf.Lerp(h,-8.25f,Mathf.SmoothStep(0,1,(x-shore)/5));
  var tp=Quaternion.Inverse(towerRot)*(p-new Vector3(towerCentre.x,0,towerCentre.z));float radius=new Vector2(tp.x,tp.z).magnitude;float flat=towerCentre.y+.1f;if(radius<5.3f)h=Mathf.Lerp(flat,h,Mathf.SmoothStep(0,1,(radius-4.25f)/1.05f));
  if(new Vector2(x,z).magnitude<4.65f||Mathf.Abs(x)<1.35f&&z<5.2f)h=.1f;
  return h;
 }
 static void Terrain(){var parent=ext.Find("02_Terrain_Littoral");foreach(var t in parent.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);
  const int nx=113,nz=139;var v=new Vector3[nx*nz];var colors=new Color[v.Length];var land=new List<int>();var cliffs=new List<int>();for(int j=0;j<nz;j++)for(int i=0;i<nx;i++){float x=-24+i*.5f,z=1.6f+j*.5f;int k=j*nx+i;Vector3 q;float d;Near(new Vector3(x,0,z),out q,out d);v[k]=new Vector3(x,Height(x,z),z);colors[k]=new Color(1-Mathf.SmoothStep(0,1,(d-.55f)/.65f),.5f,.5f,1);if(i<nx-1&&j<nz-1){if(new Vector2(x+.25f,z+.25f).magnitude<3.45f)continue;var ts=x>Mathf.Max(q.x+2.4f,6.2f+1.4f*Mathf.Sin(z*.11f))?cliffs:land;ts.AddRange(new[]{k,k+nx,k+1,k+1,k+nx,k+nx+1});}}
  Surface("Sol_Chemin_Littoral",MeshAsset("Terrain_Cotier_35m",v,land.ToArray(),colors),soil,parent,true);Surface("Falaises_Granitiques",MeshAsset("Falaise_Continue_35m",v,cliffs.ToArray(),v.Select(p=>new Color(.66f,.63f,.56f,1)).ToArray()),rock,parent,true);
  var vv=new List<Vector3>();var tt=new List<int>();Action<Vector3,Vector3> edge=(a,b)=>{int k=vv.Count;vv.Add(a);vv.Add(b);vv.Add(new Vector3(b.x,-9,b.z));vv.Add(new Vector3(a.x,-9,a.z));tt.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});};for(int i=0;i<nx-1;i++){edge(v[i],v[i+1]);edge(v[(nz-1)*nx+i+1],v[(nz-1)*nx+i]);}for(int j=0;j<nz-1;j++){edge(v[(j+1)*nx],v[j*nx]);edge(v[j*nx+nx-1],v[(j+1)*nx+nx-1]);}Surface("Enveloppe_Rocheuse",MeshAsset("Raccords_Immerges",vv.ToArray(),tt.ToArray(),vv.Select(p=>new Color(.62f,.59f,.52f,1)).ToArray()),rock,parent,false);
 }
 static void Tower(){var body=ext.Find("01_Tour_Genoise/Tour_Genoise_V5");var lods=new List<LOD>();for(int i=0;i<3;i++){var old=body.Find("Tour_V5_LOD"+i);var asset=AssetDatabase.LoadAssetAtPath<GameObject>(A+"/Models/Tour_V6_LOD"+i+".fbx");var go=(GameObject)PrefabUtility.InstantiatePrefab(asset,body);go.name="Tour_V6_LOD"+i;go.transform.localPosition=Vector3.zero;go.transform.localRotation=Quaternion.identity;go.transform.localScale=Vector3.Scale(go.transform.localScale,new Vector3(-1,1,1));foreach(var r in go.GetComponentsInChildren<Renderer>()){r.sharedMaterial=r.name.Contains("Chaux")||r.name.Contains("Joints")?mortar:r.name.Contains("Dallage")||r.name.Contains("Dalles")?AssetDatabase.LoadAssetAtPath<Material>("Assets/Prototype_Maquis/Art/TourGenoiseV3/Materials/Dallage_Use.mat"):stone;PrefabUtility.RecordPrefabInstancePropertyModifications(r);}if(i==0)foreach(var f in go.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.Contains("Embrasures")||f.name.Contains("Joints")))f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;lods.Add(new LOD(i==0?.30f:i==1?.12f:.006f,go.GetComponentsInChildren<Renderer>()));Record(go);if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);}body.GetComponent<LODGroup>().SetLODs(lods.ToArray());body.GetComponent<LODGroup>().RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(body.gameObject,A+"/Prefabs/Tour_Corrigee_V6.prefab");
  var arch=ext.Find("01_Tour_Genoise");var clone=UnityEngine.Object.Instantiate(arch.gameObject,ext);clone.name="07_Seconde_Tour_Genoise";second=clone.transform;second.localPosition=towerCentre;second.localRotation=towerRot;second.localScale=Vector3.one;
  foreach(var door in clone.GetComponentsInChildren<TourDoubleDoor>()){door.passage=null;door.Configure(Camera.main.transform);if(door.name.Contains("Littoral")){door.enabled=false;door.left.enabled=false;}else door.enabled=true;}
 }
 static bool KeepClear(Vector3 p,float radius){Vector3 q;float d;Near(p,out q,out d);if(d<1.2f+radius)return false;if(new Vector2(p.x,p.z).magnitude<4.75f+radius)return false;var tp=Quaternion.Inverse(towerRot)*(p-towerCentre);return new Vector2(tp.x,tp.z).magnitude>4.75f+radius;}
 static void RegroundExisting(){foreach(var parent in new[]{ext.Find("03_Vegetation_Littorale"),ext.Find("04_Rochers_Littoral")})foreach(var t in parent.Cast<Transform>().ToArray()){var local=ext.InverseTransformPoint(t.position);var rs=t.GetComponentsInChildren<Renderer>();if(rs.Length==0)continue;var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);float radius=Mathf.Max(bounds.extents.x,bounds.extents.z);if(!KeepClear(local,Mathf.Min(radius,1.6f))){UnityEngine.Object.DestroyImmediate(t.gameObject);continue;}if(local.x>13||local.z>52)continue;float min=Height(local.x,local.z);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)min=Mathf.Min(min,Height(local.x+x*radius*.6f,local.z+z*radius*.6f));float bottom=ext.InverseTransformPoint(new Vector3(bounds.center.x,bounds.min.y,bounds.center.z)).y;t.position+=ext.up*(min-bottom-(parent.name.Contains("Rochers")?.12f:.035f));Record(t.gameObject);}}
 static void Populate(){var plants=ext.Find("03_Vegetation_Littorale");var rocks=ext.Find("04_Rochers_Littoral");var botanical=AssetDatabase.LoadAssetAtPath<Material>(V+"/Materials/Botanique_Fibres_Nervures.mat");
  // A low evergreen variant reuses the fine branched, narrow-leaved shrub meshes.
  var juniperMat=CopyMat(botanical,"Genevrier_Feuillage_Sombre");juniperMat.SetColor("_BaseColor",new Color(.74f,.80f,.66f));
  var plantPaths=AssetDatabase.FindAssets("t:Prefab",new[]{V+"/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).ToArray();int added=0;
  for(float s=4;s<34;s+=R(.9f,1.45f))for(int side=-1;side<=1;side+=2){if(side==1&&(s>6&&s<10||s>16&&s<21||s>27&&s<32))continue;var p=ext.InverseTransformPoint(route.WorldAt(s));var d=ext.InverseTransformDirection(route.Direction(s));var n=Vector3.Cross(Vector3.up,d).normalized;float off=side==1?R(2.0f,3.1f):R(2.3f,4.4f);p+=n*side*off;string species=side==1?(added%3==0?"Bruyere":"Immortelle"):added%5==0?"Myrte":added%4==0?"Ciste":"Lentisque";float height=species=="Immortelle"?R(.25f,.48f):species=="Bruyere"?R(.75f,1.25f):side==1?R(.5f,.8f):R(.9f,1.7f);if(!KeepClear(p,height*.5f))continue;var choices=plantPaths.Where(x=>System.IO.Path.GetFileName(x).StartsWith(species+"_")).ToArray();var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(choices[added%choices.Length]);var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,plants);go.transform.localPosition=new Vector3(p.x,Height(p.x,p.z)-.035f,p.z);go.transform.localRotation=Quaternion.Euler(R(-4,4),R(0,360),R(-4,4));var lg=go.GetComponent<LODGroup>();var rs=lg?lg.GetLODs()[0].renderers:go.GetComponentsInChildren<Renderer>();var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);go.transform.localScale*=height/Mathf.Max(.1f,bounds.size.y);go.transform.localScale=Vector3.Scale(go.transform.localScale,new Vector3(R(.85f,1.15f),1,R(.85f,1.15f)));if(species=="Bruyere"){go.name="Genevrier_Phenicie_Variante_"+added;foreach(var r in go.GetComponentsInChildren<Renderer>())r.sharedMaterial=juniperMat;}Record(go);added++;}
  for(float s=3;s<34;s+=R(2.1f,3.1f))for(int side=-1;side<=1;side+=2){if(side==1&&s>7&&s<11||side==1&&s>17&&s<22)continue;var p=ext.InverseTransformPoint(route.WorldAt(s));var dir=ext.InverseTransformDirection(route.Direction(s));p+=Vector3.Cross(Vector3.up,dir).normalized*side*R(3.0f,4.2f);float scale=side<0?R(.9f,1.4f):R(.55f,.9f);if(!KeepClear(p,1.5f*scale))continue;Rock(p,scale,rocks);}
  for(int i=0;i<10;i++){float a=i*Mathf.PI*2/10;var p=towerCentre+new Vector3(Mathf.Sin(a)*5.2f,0,Mathf.Cos(a)*5.2f);var tp=Quaternion.Inverse(towerRot)*(p-towerCentre);if(tp.z<0&&Mathf.Abs(tp.x)<2.2f)continue;Rock(p,R(.6f,1.0f),rocks);}
 }
 static void Rock(Vector3 p,float scale,Transform parent){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(V+"/Prefabs/Granit_V2_"+rng.Next(0,6)+".prefab");var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,parent);go.transform.localPosition=new Vector3(p.x,Height(p.x,p.z),p.z);go.transform.localRotation=Quaternion.Euler(R(-12,12),R(0,360),R(-10,10));go.transform.localScale=Vector3.one*scale;var lg=go.GetComponent<LODGroup>();var rs=lg?lg.GetLODs()[0].renderers:go.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);Vector3 near;float d;Near(p,out near,out d);if(d<1.25f+Mathf.Max(b.extents.x,b.extents.z)){UnityEngine.Object.DestroyImmediate(go);return;}go.transform.position+=Vector3.up*(ext.TransformPoint(new Vector3(p.x,Height(p.x,p.z),p.z)).y-b.min.y-.15f);foreach(var c in go.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);var vs=new List<Vector3>();foreach(var r in rs){var f=r.GetComponent<MeshFilter>();var bb=f.sharedMesh.bounds;for(int x=-1;x<=1;x+=2)for(int y=-1;y<=1;y+=2)for(int z=-1;z<=1;z+=2)vs.Add(go.transform.InverseTransformPoint(f.transform.TransformPoint(bb.center+Vector3.Scale(bb.extents,new Vector3(x,y,z)))));}var local=new Bounds(vs[0],Vector3.zero);foreach(var v in vs)local.Encapsulate(v);var box=go.AddComponent<BoxCollider>();box.center=local.center;box.size=local.size;Record(go);}
 static void Corridor(){var corridor=GameObject.Find("Joueur_Desktop").GetComponent<SentierCorridor>();var old=corridor.CentreLine;var so=new SerializedObject(corridor);var widths=so.FindProperty("sectionHalfWidths");var start=route.WorldAt(0);int last=Enumerable.Range(0,old.Length).OrderBy(i=>Vector3.Distance(old[i],start)).First();var line=old.Take(last+1).ToList();var ww=Enumerable.Range(0,last+1).Select(i=>widths.arraySize==old.Length?widths.GetArrayElementAtIndex(i).floatValue:.58f).ToList();foreach(var p in points.Skip(1)){line.Add(ext.TransformPoint(p));ww.Add(.65f);}for(int i=0;i<=65;i++){float z=Mathf.Lerp(-4.15f,.15f,i/65f);line.Add(second.TransformPoint(new Vector3(0,.1f,z)));ww.Add(Mathf.Abs(z)>2.4f?.62f:Mathf.Sqrt(Mathf.Max(.4f,3.05f*3.05f-z*z)));}corridor.Configure(line.ToArray(),.65f);corridor.ConfigureWidths(ww.ToArray());EditorUtility.SetDirty(corridor);}
 public static string Build(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");if(GameObject.Find("07_Seconde_Tour_Genoise"))throw new Exception("Already installed");rng=new System.Random(241026);AssetDatabase.Refresh();foreach(var n in new[]{"Tour_V6_LOD0","Tour_V6_LOD1","Tour_V6_LOD2"}){var path=A+"/Models/"+n+".fbx";var imp=AssetImporter.GetAtPath(path) as ModelImporter;imp.isReadable=true;imp.importCameras=false;imp.importLights=false;imp.SaveAndReimport();}
  ext=GameObject.Find("Extension_Tour_Littoral").transform;route=ext.GetComponent<TourLittoralRoute>();stone=CopyMat(AssetDatabase.LoadAssetAtPath<Material>("Assets/Prototype_Maquis/Art/TourLittoral/Materials/Pierre_Tour_Peinte.mat"),"Granit_Tour_Unifie");stone.SetColor("_BaseColor",new Color(.95f,.93f,.89f));stone.SetColor("_ShadowTint",new Color(.54f,.53f,.48f));mortar=CopyMat(AssetDatabase.LoadAssetAtPath<Material>("Assets/Prototype_Maquis/Art/TourGenoiseV3/Materials/Chaux_Granulee.mat"),"Joints_Pierre_Naturels");mortar.SetColor("_BaseColor",new Color(.48f,.45f,.39f));soil=AssetDatabase.LoadAssetAtPath<Material>("Assets/Prototype_Maquis/Art/TourLittoral/Materials/Terre_Littorale.mat");rock=AssetDatabase.LoadAssetAtPath<Material>(V+"/Materials/Granit_Quartz_Mica.mat");Path();Tower();Terrain();RegroundExisting();Populate();Corridor();
  var z=ext.GetComponent<TourZoneSeparation>();var addedRenderers=ext.Find("02_Terrain_Littoral").GetComponentsInChildren<Renderer>().Concat(ext.Find("03_Vegetation_Littorale").GetComponentsInChildren<Renderer>()).Concat(ext.Find("04_Rochers_Littoral").GetComponentsInChildren<Renderer>()).Concat(second.GetComponentsInChildren<Renderer>()).Where(r=>!r.name.Contains("Collision")).ToArray();var keep=z.littoralRenderers.Select((r,i)=>new{r,on=i<z.littoralInitial.Length?z.littoralInitial[i]:true}).Where(x=>x.r&&!addedRenderers.Contains(x.r)).ToArray();z.littoralRenderers=keep.Select(x=>x.r).Concat(addedRenderers).Distinct().ToArray();z.littoralInitial=z.littoralRenderers.Select(r=>keep.Any(x=>x.r==r)?keep.First(x=>x.r==r).on:true).ToArray();z.maquisColliders=GameObject.Find("Maquis_35m").GetComponentsInChildren<Collider>();z.maquisColliderInitial=z.maquisColliders.Select(c=>c.enabled).ToArray();z.littoralColliders=ext.Find("02_Terrain_Littoral").GetComponentsInChildren<Collider>().Concat(ext.Find("04_Rochers_Littoral").GetComponentsInChildren<Collider>()).Concat(second.GetComponentsInChildren<Collider>()).ToArray();z.littoralColliderInitial=z.littoralColliders.Select(c=>c.enabled).ToArray();z.ApplySide(TourZoneSeparation.Side.Maquis);EditorUtility.SetDirty(z);EditorUtility.SetDirty(route);var future=ext.Find("06_Reperes_Parcours/Prolongement_Futur_Littoral");if(future){future.name="Arrivee_Seconde_Tour_35m";future.position=route.WorldAt(route.Length);}AssetDatabase.SaveAssets();Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());return "Littoral="+route.Length.ToString("F4")+"m; secondTower="+towerCentre.ToString("F3")+"; routePoints="+points.Length;}
